// PostFast returns either a raw array of account objects, or {data: [...]},
// depending on version. Normalise both into a platform → socialMediaId map.

const raw = $input.all().map(i => i.json);
let accounts = raw;
if (raw.length === 1 && raw[0] && typeof raw[0] === 'object') {
  if (Array.isArray(raw[0].data)) accounts = raw[0].data;
  else if (Array.isArray(raw[0].items)) accounts = raw[0].items;
  else if (Array.isArray(raw[0].results)) accounts = raw[0].results;
}

const platformMap = {};
const summary = [];
for (const acc of accounts) {
  if (!acc || !acc.id) continue;
  const platform = String(acc.platform || acc.provider || '').toUpperCase();
  if (!platform) continue;
  platformMap[platform] = acc.id;
  summary.push({ platform, id: acc.id, handle: acc.handle || acc.name || null });
}

return [{ json: { platformMap, summary, rawCount: accounts.length } }];

// Explode each Notion short into one item per (platform-post).
// Each output item is a FULLY FORMED PostFast POST /social-posts body
// with platform-specific `controls` — because PostFast applies controls
// to every post in the batch, so we can't mix platforms in one call.
//
// Expected Notion properties:
//   Titre (title)
//   Description (text with YT:/SM:/LI:/X: prefixed blocks)
//   Date de Publication (date)
//   PostFast Media Key (text, e.g. 'video/<uuid>.mp4') — REQUIRED

const PLATFORM_CONFIG = {
  YT: [
    { platform: 'YOUTUBE', controls: { youtubeIsShort: true } }
  ],
  SM: [
    { platform: 'INSTAGRAM', controls: { instagramPublishType: 'REEL', instagramPostToGrid: true } },
    { platform: 'TIKTOK',    controls: { tiktokPrivacy: 'PUBLIC', tiktokAllowComments: true, tiktokAllowDuet: true } }
  ],
  LI: [
    { platform: 'LINKEDIN', controls: {} }
  ],
  X: [
    { platform: 'X',        controls: {} }
  ],
};

const platformMap = $('Code — Build Platform Map').first().json.platformMap || {};

const extractText = (v) => {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(r => r.plain_text || r.text?.content || r.text || '').join('');
  if (typeof v === 'object') {
    if (v.plain_text) return v.plain_text;
    if (typeof v.text === 'string') return v.text;
    if (Array.isArray(v.title)) return v.title.map(r => r.plain_text || '').join('');
    if (Array.isArray(v.rich_text)) return v.rich_text.map(r => r.plain_text || '').join('');
  }
  return String(v ?? '');
};

const extractDate = (v) => {
  if (!v) return null;
  if (typeof v === 'string') return v;
  if (v.start) return v.start;
  if (v.date && v.date.start) return v.date.start;
  return null;
};

const props = $json.properties || $json;
const titleText = extractText(props['Titre']);
const descText = extractText(props['Description']);
const dateRaw = extractDate(props['Date de Publication']);
const mediaKey = extractText(props['PostFast Media Key']).trim();
const notionPageId = $json.id || ($json.url && $json.url.split('/').pop().split('?')[0]) || '';

if (!dateRaw) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}) has no Date de Publication.`);
}
if (!mediaKey) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}) has no 'PostFast Media Key'. Upload the video with scripts/upload-video.sh and paste the returned key (format: video/<uuid>.mp4) into the Notion property.`);
}

// Default post time = 09:00 UTC on the publication date.
const scheduledAt = /T\d/.test(dateRaw)
  ? new Date(dateRaw).toISOString()
  : new Date(`${dateRaw}T09:00:00.000Z`).toISOString();

const mediaItems = [
  { key: mediaKey, type: 'VIDEO', sortOrder: 0, coverTimestamp: '2000' }
];

// Split Description into per-prefix blocks.
const BLOCK_REGEX = /(^|\n)\s*(YT|SM|LI|X)\s*:\s*/g;
const matches = [];
let m;
while ((m = BLOCK_REGEX.exec(descText)) !== null) {
  matches.push({ prefix: m[2], start: m.index + m[0].length });
}
if (matches.length === 0) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}) has no YT:/SM:/LI:/X: blocks in its Description.`);
}

const blocks = [];
for (let i = 0; i < matches.length; i++) {
  const end = i + 1 < matches.length
    ? matches[i + 1].start - matches[i + 1].prefix.length - 2
    : descText.length;
  let caption = descText.slice(matches[i].start, end).trim();
  caption = caption.replace(/\s*\|\s*Tags\s*:.*$/is, '').trim();
  blocks.push({ prefix: matches[i].prefix, caption });
}

const output = [];
const missingPlatforms = [];
for (const { prefix, caption } of blocks) {
  const configs = PLATFORM_CONFIG[prefix] || [];
  for (const { platform, controls } of configs) {
    const socialMediaId = platformMap[platform];
    if (!socialMediaId) {
      missingPlatforms.push(platform);
      continue;
    }
    output.push({
      json: {
        notionPageId,
        titleText,
        platform,
        body: {
          posts: [
            {
              content: caption,
              scheduledAt,
              socialMediaId,
              mediaItems,
            },
          ],
          controls,
        },
      },
    });
  }
}

if (output.length === 0) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}): no posts could be built. Missing platforms in PostFast workspace: ${missingPlatforms.join(', ') || 'none'}.`);
}

return output;
